## Background

Alternative implementation to #5262 which doesn't introduce a 2nd argument for a model constructor, which would break our provider registry feature

related:

- https://github.com/vercel/ai/issues/8475#issuecomment-3264158527
- https://github.com/vercel/ai/pull/8428
- https://github.com/vercel/ai/issues/8427

## Summary

Introduce a new `supportsStructuredOutputs` option to `createOpenAICompatible()` that gets passed to `provider.languageModel` and `provider.chatModel`

## Manual Verification

```ts
import 'dotenv/config';
import { createOpenAICompatible } from '@ai-sdk/openai-compatible';
import { generateObject } from 'ai';
import { z } from 'zod/v4';

async function main() {
  const togetherai = createOpenAICompatible({
    baseURL: 'https://api.together.xyz/v1',
    name: 'togetherai',
    headers: {
      Authorization: `Bearer ${process.env.TOGETHER_AI_API_KEY}`,
    },
    supportsStructuredOutputs: true,
  });
  const model = togetherai.chatModel('mistralai/Mistral-7B-Instruct-v0.1');
  const result = await generateObject({
    model,
    schema: z.object({
      recipe: z.object({
        name: z.string(),
        ingredients: z.array(
          z.object({
            name: z.string(),
            amount: z.string(),
          }),
        ),
        steps: z.array(z.string()),
      }),
    }),
    prompt: 'Generate a lasagna recipe.',
  });

  console.log(JSON.stringify(result.object.recipe, null, 2));
  console.log();
  console.log('Token usage:', result.usage);
  console.log('Finish reason:', result.finishReason);
}

main().catch(console.error);
```

